"use client"

import type { ComponentProps, CSSProperties } from "react"
import { cn } from "cn"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./aspect-ratio.css"

function AspectRatio({
  ratio,
  className,
  style,
  ...props
}: ComponentProps<"div"> & {
  ratio: number
}) {
  return (
    <div
      data-slot="aspect-ratio"
      style={{ "--np-aspect-ratio-value": ratio, ...style } as CSSProperties}
      className={cn("np-aspect-ratio", className)}
      {...props}
    />
  )
}

export { AspectRatio }

/* nepui - Aspect Ratio */

.np-aspect-ratio,
[data-np-aspect-ratio] {
  --np-aspect-ratio-value: 16 / 9;
  --np-aspect-ratio-fit: cover;

  position: relative;
  box-sizing: border-box;
  aspect-ratio: var(--np-aspect-ratio-value);
}

:is(.np-aspect-ratio, [data-np-aspect-ratio]) > :is(img, video, iframe) {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
  object-fit: var(--np-aspect-ratio-fit);
}

.np-aspect-ratio-square,
:is(.np-aspect-ratio, [data-np-aspect-ratio])[data-ratio="square"] {
  --np-aspect-ratio-value: 1 / 1;
}

.np-aspect-ratio-portrait,
:is(.np-aspect-ratio, [data-np-aspect-ratio])[data-ratio="portrait"] {
  --np-aspect-ratio-value: 9 / 16;
}
